SELECT

FROM user_card uc
         JOIN card_product cp ON cp.card_product_id = uc.card_product_id
WHERE uc.user_id = #{userId}
  AND uc.user_card_id = #{userCardId}
  AND uc.is_deleted = 0

SELECT

FROM user_card uc
         JOIN card_product cp ON cp.card_product_id = uc.card_product_id
WHERE uc.user_id = #{userId}
  AND uc.card_product_id = #{cardProductId}
  AND uc.is_deleted = 0

SELECT is_deleted
FROM user_card
WHERE user_id = #{userId}
  AND card_product_id = #{cardProductId}

