UPDATE user_card
SET is_deleted    = 0,
    first4        = #{request.first4},
    last4         = #{request.last4},
    expiry_date   = #{request.expiryDate},
    display_order = #{displayOrder}
WHERE user_id = #{userId}
  AND card_product_id = #{request.cardProductId}
